begin;
select set_config('cms_test.admin',gen_random_uuid()::text,true);
select set_config('cms_test.cat','cms-category-'||gen_random_uuid()::text,true);
insert into auth.users(id,aud,role,email) values(current_setting('cms_test.admin')::uuid,'authenticated','authenticated','cms-category-fixture@cms-test.invalid');
select set_config('request.jwt.claim.sub',current_setting('cms_test.admin'),true);
set local role authenticated;
do $$begin begin insert into public.categories(id,name,slug,sort_order) values(current_setting('cms_test.cat'),'금지된 분류',current_setting('cms_test.cat'),99);raise exception 'Ordinary category write accepted';exception when insufficient_privilege then null;end;end $$;
reset role;
insert into public.admin_users(user_id,username) values(current_setting('cms_test.admin')::uuid,'cms_category_fixture');
set local role authenticated;
insert into public.categories(id,name,slug,sort_order) values(current_setting('cms_test.cat'),current_setting('cms_test.cat'),current_setting('cms_test.cat'),99);
insert into public.posts(environment,title,slug,summary,content,category_id,status) values('preview','카테고리 기능 검사',current_setting('cms_test.cat'),repeat('가',125),'[{"type":"text","text":"본문"}]',current_setting('cms_test.cat'),'published');
update public.categories set is_active=false where id=current_setting('cms_test.cat');
set local role anon;
do $$begin if exists(select 1 from public.posts where category_id=current_setting('cms_test.cat')) then raise exception 'Inactive category post was exposed';end if;if exists(select 1 from public.categories where id=current_setting('cms_test.cat')) then raise exception 'Inactive category was exposed';end if;end $$;
set local role authenticated;
update public.categories set is_active=true,sort_order=100,name=current_setting('cms_test.cat')||'-수정' where id=current_setting('cms_test.cat');
do $$begin if not exists(select 1 from public.posts where category_id=current_setting('cms_test.cat')) then raise exception 'Category post was lost';end if;if (select count(*) from public.categories where id in ('implant','complex-implant','full-implant','sedation','orthodontics'))<>5 then raise exception 'Original categories changed';end if;end $$;
set local role anon;
do $$begin if not exists(select 1 from public.posts where category_id=current_setting('cms_test.cat')) then raise exception 'Reactivated category not public';end if;end $$;
reset role;
rollback;
